const CANOPY_SECTIONS = [
  // [z, halfWidth, baseY, topY]
  [2.30, 0.50, 0.52, 1.16],
  [1.20, 0.58, 0.55, 1.30],
  [0.35, 0.55, 0.55, 1.24],
