function ringPoint(ring, k) {
  const a = (k * Math.PI) / 4;
  return [ring[1] * Math.sin(a), ring[3] + ring[2] * Math.cos(a), ring[0]];
}

// Chase view: build the face list in her frame, turn it by her
// attitude, light it, sort it, paint it.
