  const fw = Math.max(0, (w - 3) * Math.min(1, frac));
  if (fw > 2) {
    const grad = ctx.createLinearGradient(x, y, x, y + h);
    grad.addColorStop(0, '#ffffff');
    grad.addColorStop(0.18, colour);
    grad.addColorStop(1, colour);
