    ctx.beginPath();
    ctx.moveTo(x + w * q, y + 2);
    ctx.lineTo(x + w * q, y + h - 2);
    ctx.stroke();
  }
  ctx.fillStyle = '#dfeaf2';
  ctx.font = `700 ${Math.max(8, h * 0.72)}px system-ui, sans-serif`;
