  const bezel = ctx.createRadialGradient(x - r * 0.4, y - r * 0.45, r * 0.3, x, y, r * 1.09);
  bezel.addColorStop(0, '#5d6f82');
  bezel.addColorStop(0.55, '#2c3947');
  bezel.addColorStop(1, '#12181f');
