  ctx.strokeStyle = '#48586a';
  ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.arc(x, y, r * 0.97, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = 'rgba(190,225,255,0.10)';
  ctx.beginPath(); ctx.ellipse(x - r * 0.3, y - r * 0.44, r * 0.44, r * 0.2, -0.6, 0, Math.PI * 2); ctx.fill();
}

