  ctx.fillStyle = '#9fb6c6';
  ctx.font = `600 ${Math.max(8, r * 0.24)}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.fillText(text, x, y + r * 0.68 + r + 8);
}
